const projects=[
{name:'나 수놓기',theme:'자기 이해',book:'나는 단단한 아이',desc:'작품 속 인물을 이해하고 나의 경험과 연결합니다. 나만의 강점과 가치를 발견하고, 글과 그림으로 나를 표현합니다.',output:'『나는 ○○ 아이』 나만의 책',questions:['작품에는 어떤 이야기가 숨어 있을까?','‘단단한 아이’는 어떤 아이일까?','인물이 소중히 여기는 가치는 무엇일까?','가치를 나의 삶에서는 어떻게 실천할까?','나의 강점과 가치를 어떻게 책에 담을까?','나를 보여 주는 책을 어떻게 완성할까?','책을 나누며 서로의 어떤 가치를 발견할까?','새롭게 발견한 나의 강점을 어떻게 이어 갈까?'],activities:['제목·표지·소개글에서 단서를 찾고 인물과 이야기를 예상합니다.','낯선 낱말과 주요 사건을 이해하고, 생각 질문을 만들어 작품의 주제를 찾습니다.','인물의 말과 행동에서 마음을 짐작하고 근거를 찾아 가치를 탐색합니다.','비슷한 나의 경험을 떠올리고 중요한 가치와 실천 과제를 정합니다.','나의 경험에서 강점을 발견하고 책의 제목과 내용을 계획합니다.','경험을 글과 그림으로 표현하고 친구 의견을 반영해 책을 완성합니다.','완성한 책을 전시·소개하고 친구의 책에서 발견한 가치를 나눕니다.','연계 학급과 책을 교환하고 방명록을 남기며 앞으로의 행동을 정합니다.']},
{name:'너 수놓기',theme:'타인 이해',book:'아몬드',desc:'같은 장면을 서로 다른 인물의 눈으로 바라봅니다. 나의 편견을 돌아보고, 열린 질문과 경청으로 타인의 경험과 마음을 헤아립니다.',output:'질문과 경청으로 만드는 헤아림 인터뷰',questions:['인물의 행동에는 어떤 이유가 숨어 있을까?','인물의 마음은 어떤 단서로 이해할까?','같은 장면이 왜 다르게 보일까?','나도 누군가를 미리 판단한 적이 있을까?','상대를 이해하려면 무엇을 물어야 할까?','상대의 이야기를 어떻게 듣고 기록할까?','인터뷰 후 나의 생각은 어떻게 달라졌을까?','타인을 이해하는 태도를 어떻게 이어 갈까?'],activities:['표지와 소개글로 이야기를 예상하고 낱말과 감정 표현의 뜻을 짐작합니다.','인물과 주요 사건을 정리하고 행동의 까닭을 묻는 질문을 만듭니다.','인물별 상황과 마음을 살피고 작품 속 근거로 서로 다른 관점을 비교합니다.','읽기 전후의 생각을 비교하며 편견을 돌아보고 실천 행동을 정합니다.','인터뷰 대상과 알아볼 경험을 정하고 열린 질문을 만듭니다.','헤아림 인터뷰를 진행하며 추가 질문을 잇고 답변의 핵심을 기록합니다.','인터뷰 전후의 생각을 비교하고 새롭게 이해한 내용을 나눕니다.','연계 학급과 인터뷰하고 실천 과제를 돌아보며 이어 갈 행동을 정합니다.']},
{name:'우리 수놓기',theme:'공동체 이해',book:'나나 올리브에게',desc:'문학 속 관계에서 함께 살아가는 가치를 발견합니다. 우리에게 필요한 가치를 정하고, 공동의 메시지를 공익광고로 만들어 세상과 나눕니다.',output:'함께 만드는 가치 공익광고',questions:['작품 속 인물들은 어떻게 이어져 있을까?','함께 살아가는 데 필요한 가치는 무엇일까?','사람과 사람을 이어 주는 힘은 무엇일까?','우리에게 필요한 가치는 무엇일까?','공동체 가치를 어떻게 광고에 담을까?','함께 만든 생각을 어떻게 영상으로 표현할까?','우리 광고의 가치는 어떻게 전달되었을까?','공동체 가치를 어떻게 더 넓게 이어 갈까?'],activities:['제목·표지·소개글로 이야기를 예상하고 낱말과 표현의 의미를 이해합니다.','인물과 사건·관계를 정리하고 질문을 통해 공동체 가치를 찾습니다.','인물 관계망을 만들고 관계를 이어 주는 공동체 가치를 발견합니다.','연계 학급과 근거를 나누며 공동의 가치와 실천 방법을 정합니다.','광고의 대상과 목적을 정하고 핵심 메시지와 장면을 구성합니다.','스토리보드를 공유하고 표현 방법을 협의하여 공익광고를 제작합니다.','상영회에서 메시지와 표현을 살펴보고 피드백으로 효과를 돌아봅니다.','광고를 공유하고 다양한 반응을 나누며 실천 약속을 정합니다.']}
];
function showProject(index){const p=projects[index];document.querySelectorAll('[data-project]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1});const panel=document.querySelector('#project-panel');panel.setAttribute('aria-labelledby',`tab-${index}`);panel.innerHTML=`<div class="project-main"><div class="book-side"><div class="book"><small>함께 읽는 책</small><strong>${p.book}</strong><i>✧</i></div><p>문학에서 발견한 가치를 삶으로</p></div><div class="project-content"><p class="eyebrow">${['첫 번째 은하','두 번째 은하','세 번째 은하'][index]} / ${p.theme}</p><h3>${p.name}, ${['나만의 빛을 찾는 시간','서로의 마음을 만나는 시간','함께 가치를 실천하는 시간'][index]}</h3><p>${p.desc}</p><div class="project-facts"><span>초등 5·6학년</span><span>8차시</span><span>국어 · 도덕${index===2?' · 미술':''}</span></div><div class="project-output"><b>배움의 결과물</b> ${p.output}</div></div></div><div class="lesson-list"><h4>8차시 수업 여정 <small>· 차시를 누르면 활동이 펼쳐집니다.</small></h4>${p.questions.map((q,i)=>`<details><summary><span class="lesson-stage lesson-stage-${Math.floor(i/2)}" aria-label="${['보며읽기','물음잇기','지혜짓기','도전하기'][Math.floor(i/2)]}">${['보','물','지','도'][Math.floor(i/2)]}</span><small>${i+1}차시</small><span>${q}</span><span>＋</span></summary><p>${p.activities[i]}</p></details>`).join('')}</div>`;setupStageTabs(index);}
function setupStageTabs(projectIndex){
 const list=document.querySelector('.lesson-list');
 const lessons=Array.from(list.querySelectorAll('details'));
 const names=['보며읽기','물음잇기','지혜짓기','도전하기'];
 const images=['step-read.png','step-question.png','step-create.png','step-action.png'];
 list.querySelector('h4 small').textContent='· 차시를 누르면 활동이 펼쳐집니다.';
 for(let stage=0;stage<4;stage++){
  const group=document.createElement('div');group.className='lesson-stage-group';
  const marker=document.createElement('div');marker.className='lesson-group-marker';
  const image=document.createElement('img');image.src='assets/'+images[stage];image.alt=names[stage];image.width=48;image.height=57;marker.append(image);
  const rows=document.createElement('div');rows.className='lesson-group-rows';
  lessons.slice(stage*2,stage*2+2).forEach(lesson=>{lesson.querySelector('.lesson-stage').remove();rows.append(lesson)});
  group.append(marker,rows);list.append(group);
 }
}
document.querySelectorAll('[data-project]').forEach(b=>{b.addEventListener('click',()=>showProject(Number(b.dataset.project)));b.addEventListener('keydown',e=>{let i=Number(b.dataset.project);if(e.key==='ArrowRight')i=(i+1)%3;else if(e.key==='ArrowLeft')i=(i+2)%3;else if(e.key==='Home')i=0;else if(e.key==='End')i=2;else return;e.preventDefault();showProject(i);document.querySelector(`#tab-${i}`).focus()})});showProject(0);
const resources=[{name:'은하수 프로젝트 교수·학습 자료',desc:'프로젝트 수업에 활용하는 교수·학습 자료 모음 · 구글 드라이브',type:'teaching',format:'자료',url:'https://drive.google.com/drive/folders/1uPWsaA05cJcG7u1ckM6mc3jCATIvVR7O?usp=sharing',action:'자료 보기 ↗'},{name:'은하수 프로젝트 학생 활동지',desc:'2026.10.25 · 프로젝트 수업에 활용하는 학생 활동지',type:'worksheet',format:'활동지',url:'materials/worksheets.pdf',action:'자료보기 ↗'},...projects.map((p,i)=>({name:p.name+' · 8차시 수업 안내',desc:p.book+' · '+p.output,type:'guide',format:'안내',project:i,action:'살펴보기 →'}))];
let filter='all';function renderResources(){const query=document.querySelector('#search').value.trim().toLowerCase();const shown=resources.filter(r=>(filter==='all'||r.type===filter)&&(r.name+' '+r.desc).toLowerCase().includes(query));document.querySelector('#resource-count').textContent=`${shown.length}개의 자료`;document.querySelector('#resource-list').innerHTML=shown.length?shown.map(r=>`<article class="resource-row"><span class="file-icon">${r.format}</span><div class="resource-info"><h3>${r.name}</h3><p>${r.desc}</p></div><a ${r.url?`href="${r.url}" ${r.type==='report'?'download':'target="_blank" rel="noopener"'}`:`href="#projects" data-open-project="${r.project}"`}>${r.action}</a></article>`).join(''):'<p class="empty">검색 결과가 없습니다. 다른 검색어를 입력해 보세요.</p>';document.querySelectorAll('[data-open-project]').forEach(a=>a.addEventListener('click',()=>showProject(Number(a.dataset.openProject))))}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderResources()}));document.querySelector('#search').addEventListener('input',renderResources);renderResources();
